import{_ as i,o as l,c as r,a2 as n}from"./chunks/framework.DSc8fo6x.js";const k=JSON.parse('{"title":"Nə dəyişib","description":"","frontmatter":{},"headers":[],"relativePath":"yenilikler.md","filePath":"yenilikler.md"}'),e={name:"yenilikler.md"};function d(t,a,s,m,o,u){return l(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="nə-dəyisib" tabindex="-1">Nə dəyişib <a class="header-anchor" href="#nə-dəyisib" aria-label="Permalink to &quot;Nə dəyişib&quot;">​</a></h1><p>Proqramın versiyaları üzrə dəyişikliklər (ən yenisi yuxarıda).</p><h2 id="_12-10-2026" tabindex="-1">12.10.2026 <a class="header-anchor" href="#_12-10-2026" aria-label="Permalink to &quot;12.10.2026&quot;">​</a></h2><ul><li>Kömək: sol aşağıda «Kömək» menyusu və hər səhifədə «?» — təlimat proqramın içində, internetsiz açılır (3 dildə).</li><li>Kassir üçün çap ediləcək qısa vərəq (PDF), klaviatura qısayolları.</li><li>Admin üçün başlanğıc siyahısı: mağaza məlumatı, ilk mal, kassir, printer, Telegram.</li><li>Onlayn təlimat, videolar və PDF-lər: camalzadeh.github.io/kassa-docs</li><li>Məşq rejimi: yeni kassir satış etməyi öyrənir, satışlar yazılmır (yalnız admin açır, müddətlə).</li><li>Düzəliş: Ayarlarda yazılıb hələ saxlanmamış dəyişikliklər yavaş kompüterdə özü-özünə silinə bilirdi.</li></ul><h2 id="_12-10-2026-1" tabindex="-1">12.10.2026 <a class="header-anchor" href="#_12-10-2026-1" aria-label="Permalink to &quot;12.10.2026&quot;">​</a></h2><ul><li>Telegram: «Çatı tap» və «Sınaq mesajı» uğurlu olanda token və çat özü yadda saxlanılır.</li><li>Bütün ayarlar (default dəyərlər də) bazada saxlanılır — baza köçəndə hər şey eynilə qayıdır.</li><li>Köhnə qara ikon əvəzinə hər yerdə yeni Kassa loqosu görünür.</li></ul><h2 id="_11-10-2026" tabindex="-1">11.10.2026 <a class="header-anchor" href="#_11-10-2026" aria-label="Permalink to &quot;11.10.2026&quot;">​</a></h2><ul><li>Çek və etiket printeri (məs. Xprinter): Ayarlar → Printerlər. Qəbz və etiket pəncərəsiz, birbaşa printerə gedir; sınaq çapı.</li><li>Satış bitəndə qəbz özü çap oluna bilər; yoxdursa, yaşıl bildirişdəki «Qəbz» düyməsi.</li><li>Nağd satışda kassa qutusu açıla bilər (qutu printerə qoşulubsa).</li><li>Yeni etiket ölçüləri: 50×30, 40×30, 30×20 mm.</li><li>Telegram: qrupa göndərmək düzəldi — «Çatı tap» bir neçə çat tapanda siyahıdan seçirsiniz.</li><li>Telegram 2 gündən çox işləməsə və ya bazada pozuntu tapılsa, admin əsas ekranda xəbərdarlıq görür.</li><li>Skan yarıda kəsilmir (barkod iki hissəyə bölünmürdü); bərpadan sonra ekran donmur.</li><li>Yeni quraşdırma üçün quraşdırma parolu lazımdır.</li></ul><h2 id="_07-10-2026" tabindex="-1">07.10.2026 <a class="header-anchor" href="#_07-10-2026" aria-label="Permalink to &quot;07.10.2026&quot;">​</a></h2><ul><li>Dillər: Azərbaycan, rus, ingilis. Hər istifadəçi öz dilini menyudan seçə bilər.</li><li>Yeni «Ayarlar» bölməsi: mağaza məlumatları (qəbzdə görünür), tema, yazı ölçüsü, kilid vaxtı, backup və s. Bütün ayarlar bazada saxlanılır.</li><li>Yeniləmədən əvvəl baza avtomatik backup olunur; proqramın köhnə versiyası yeni bazanı açmır.</li><li>Baza silinsə və ya zədələnsə, proqram təzə baza yaratmır — bərpa ekranı açılır (bərpa kodu ilə).</li><li>Backup-ı proqramın içindən bərpa etmək və bazanı başqa diskə köçürmək mümkündür.</li><li>Baza proqram bağlı ikən köhnə nüsxə ilə əvəz edilsə, admin xəbərdar edilir.</li><li>Yeniləmələr imzalıdır: proqram yalnız rəsmi versiyanı quraşdırır (internetdən və ya fayldan).</li><li>Telegram: gündəlik hesabat və şifrəli backup sahibin telefonuna.</li></ul>',10)])])}const y=i(e,[["render",d]]);export{k as __pageData,y as default};
